package trie

import "testing"

func TestInsertSearch(t *testing.T) {
	tr := New()
	tr.Insert("apple")
	if !tr.Search("apple") {
		t.Error("Search(apple) should be true")
	}
	if tr.Search("app") {
		t.Error("Search(app) should be false — not inserted")
	}
}

func TestStartsWith(t *testing.T) {
	tr := New()
	tr.Insert("apple")
	tr.Insert("app")
	if !tr.StartsWith("app") {
		t.Error("StartsWith(app) should be true")
	}
	if tr.StartsWith("xyz") {
		t.Error("StartsWith(xyz) should be false")
	}
}

func TestMultipleWords(t *testing.T) {
	tr := New()
	words := []string{"cat", "car", "card", "care", "careful"}
	for _, w := range words {
		tr.Insert(w)
	}
	for _, w := range words {
		if !tr.Search(w) {
			t.Errorf("Search(%s) should be true", w)
		}
	}
	if tr.Search("ca") {
		t.Error("Search(ca) should be false")
	}
	if !tr.StartsWith("ca") {
		t.Error("StartsWith(ca) should be true")
	}
}
